using System.Net;
using System.Net.Http.Json;
using RaceDay.Api.Dtos;
namespace RaceDay.Tests;
public class EnrolmentTests : IClassFixture<ApiFactory>
{
    readonly ApiFactory factory; public EnrolmentTests(ApiFactory factory)=>this.factory=factory;
    [Fact] public async Task ParticipantCanEnrolAndEnrolmentIsReturned(){var organiser=factory.CreateClient(new WebApplicationFactoryClientOptions{HandleCookies=true});var oe=$"org{Guid.NewGuid():N}@example.com";await organiser.PostAsJsonAsync("/api/auth/register",new RegisterRequest("Org","User",oe,"Password123!","Organiser",null));(await organiser.PostAsJsonAsync("/api/auth/login",new LoginRequest(oe,"Password123!"))).EnsureSuccessStatusCode();var created=await organiser.PostAsJsonAsync("/api/events",new EventRequest("Enrolment Event",null,DateTime.UtcNow.AddDays(10),"Venue","City","Province","Running"));var ev=await created.Content.ReadFromJsonAsync<EventResponse>();var category=await organiser.PostAsJsonAsync($"/api/events/{ev!.EventId}/categories",new CategoryRequest("10 km",10,100,100));var cat=await category.Content.ReadFromJsonAsync<CategoryResponse>();var participant=factory.CreateClient(new WebApplicationFactoryClientOptions{HandleCookies=true});var pe=$"part{Guid.NewGuid():N}@example.com";await participant.PostAsJsonAsync("/api/auth/register",new RegisterRequest("Part","User",pe,"Password123!","Participant",null));(await participant.PostAsJsonAsync("/api/auth/login",new LoginRequest(pe,"Password123!"))).EnsureSuccessStatusCode();var response=await participant.PostAsJsonAsync("/api/enrolments",new EnrolmentRequest(cat!.CategoryId,"Emergency","0700000000"));Assert.Equal(HttpStatusCode.Created,response.StatusCode);var mine=await participant.GetAsync("/api/enrolments/me");Assert.Equal(HttpStatusCode.OK,mine.StatusCode);}
    [Fact] public async Task DuplicateEnrolmentIsRejected(){var client=factory.CreateClient(new WebApplicationFactoryClientOptions{HandleCookies=true});var email=$"dup{Guid.NewGuid():N}@example.com";await client.PostAsJsonAsync("/api/auth/register",new RegisterRequest("Part","User",email,"Password123!","Participant",null));(await client.PostAsJsonAsync("/api/auth/login",new LoginRequest(email,"Password123!"))).EnsureSuccessStatusCode();var organiser=factory.CreateClient(new WebApplicationFactoryClientOptions{HandleCookies=true});var oe=$"org{Guid.NewGuid():N}@example.com";await organiser.PostAsJsonAsync("/api/auth/register",new RegisterRequest("Org","User",oe,"Password123!","Organiser",null));(await organiser.PostAsJsonAsync("/api/auth/login",new LoginRequest(oe,"Password123!"))).EnsureSuccessStatusCode();var created=await organiser.PostAsJsonAsync("/api/events",new EventRequest("Duplicate Event",null,DateTime.UtcNow.AddDays(10),"Venue","City","Province","Running"));var ev=await created.Content.ReadFromJsonAsync<EventResponse>();var catResponse=await organiser.PostAsJsonAsync($"/api/events/{ev!.EventId}/categories",new CategoryRequest("5 km",5,50,100));var cat=await catResponse.Content.ReadFromJsonAsync<CategoryResponse>();Assert.Equal(HttpStatusCode.Created,(await client.PostAsJsonAsync("/api/enrolments",new EnrolmentRequest(cat!.CategoryId,null,null))).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await client.PostAsJsonAsync("/api/enrolments",new EnrolmentRequest(cat.CategoryId,null,null))).StatusCode);}
}
